#!/usr/bin/env bash
# =====================================================================================
#  Granth — ONE FILE to install, set up and uninstall (macOS and Ubuntu/Debian Linux).
#
#    chmod +x granth_setup.sh
#    ./granth_setup.sh                 install, or update an existing install (settings, keys,
#                                      chats and index are kept; your books are never touched)
#    ./granth_setup.sh update          same as above, said explicitly
#    ./granth_setup.sh rollback        go back to the version you had before the last update
#    ./granth_setup.sh version         show the installed version and the version in this file
#    ./granth_setup.sh ai              change the AI later (Ollama / free key)
#    ./granth_setup.sh indic           add offline Indian-language translation (IndicTrans2, ~4 GB, free),
#                                      in its own Python environment; updates the app first if this file is newer
#    ./granth_setup.sh indic remove    remove IndicTrans2, its environment and its downloaded models
#    ./granth_setup.sh repair          fix Python package conflicts (pip "dependency conflicts" messages)
#    ./granth_setup.sh status | ports | logs | open | admin | start | stop | restart
#    ./granth_setup.sh uninstall       remove the app (asks before deleting chats/index; books are never deleted)
#    ./granth_setup.sh uninstall --all remove everything Granth set up: app, environments, models, data,
#                                      Ollama, the OCR tools it installed and pip's download cache
#    ./granth_setup.sh health          one-line health check for monitoring (exit code 0 = healthy)
#
#  Options (environment variables):
#    AI=ollama|key|skip   BOOKS_DIR=~/GranthBooks   PORT=8000   WITH_SEMANTIC=1|0   WITH_INDIC=0|1
#    OLLAMA_MODEL=qwen2.5:7b      PYTHON_BIN=/path/to/python3.12      SKIP_BACKUP=1
# =====================================================================================
set -uo pipefail

LABEL="com.granth.app"
HOME_DIR="$HOME/granth"
APP="$HOME_DIR/app"
VENV="$HOME_DIR/venv"
DATA="$HOME_DIR/data"
BOOKS_DIR="${BOOKS_DIR:-$HOME/GranthBooks}"
PORT="${PORT:-8000}"
ADMIN_PORT="${ADMIN_PORT:-8001}"
WITH_SEMANTIC="${WITH_SEMANTIC:-1}"
WITH_INDIC="${WITH_INDIC:-0}"
OLLAMA_MODEL="${OLLAMA_MODEL:-}"
PREV="$HOME_DIR/app.prev"
VENV_INDIC="$HOME_DIR/venv-indic"      # IndicTrans2 has its own environment: its packages clash with search's
PLIST="$HOME/Library/LaunchAgents/$LABEL.plist"
UNIT_DIR="$HOME/.config/systemd/user"
UNIT="$UNIT_DIR/granth.service"
UIDN="$(id -u)"
case "$(uname -s)" in Darwin) OSK=mac;; Linux) OSK=linux;; *) OSK=other;; esac
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"

say()  { printf '\033[1;34m==>\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33mwarn:\033[0m %s\n' "$*"; }
die()  { printf '\033[1;31mERROR:\033[0m %s\n' "$*" >&2; exit 1; }
ask()  { local a; { read -r -p "$1" a </dev/tty; } 2>/dev/null || a="${2:-}"; echo "${a:-${2:-}}"; }
has_tty() { { true </dev/tty; } 2>/dev/null; }

# ---------- settings file helpers (portable: no sed -i, works on macOS and Linux) ----------
setkv() {  # setkv KEY VALUE  -> create or replace KEY=VALUE in the settings file
  local k="$1" v="$2" f="$APP/.env" t; t="$(mktemp)"
  [ -f "$f" ] || : > "$f"
  awk -v k="$k" -v v="$v" 'BEGIN{d=0} $0 ~ "^"k"=" {print k"="v; d=1; next} {print} END{if(!d)print k"="v}' "$f" > "$t" && cat "$t" > "$f"
  rm -f "$t"; chmod 600 "$f"
}
delkv() {  # delkv KEY  -> remove KEY from the settings file
  local k="$1" f="$APP/.env" t; [ -f "$f" ] || return 0; t="$(mktemp)"
  awk -v k="$k" '$0 !~ "^"k"=" {print}' "$f" > "$t" && cat "$t" > "$f"; rm -f "$t"; chmod 600 "$f"
}

# ---------- operating-system helpers ----------
as_root() {     # run a command as root (apt); asks for the password once through sudo
  if [ "$(id -u)" = 0 ]; then "$@"; elif command -v sudo >/dev/null 2>&1; then sudo "$@"; else return 1; fi
}
open_url() {
  if [ "$OSK" = mac ]; then open "$1" >/dev/null 2>&1 || true
  elif [ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ] && command -v xdg-open >/dev/null 2>&1; then xdg-open "$1" >/dev/null 2>&1 || true
  else echo "  open in a browser: $1"; fi
}
mem_gb() {
  if [ "$OSK" = mac ]; then echo $(( $(sysctl -n hw.memsize 2>/dev/null || echo 8589934592) / 1073741824 ))
  else awk '/MemTotal/{print int($2/1048576)}' /proc/meminfo 2>/dev/null || echo 8; fi
}
svc_mode() {    # mac: launchd | linux: systemd (per-user service) or plain (background process + @reboot)
  if [ "$OSK" = mac ]; then echo launchd; return; fi
  if [ -f "$HOME_DIR/.service-mode" ]; then cat "$HOME_DIR/.service-mode"; return; fi
  if command -v systemctl >/dev/null 2>&1 && systemctl --user show-environment >/dev/null 2>&1; then echo systemd; else echo plain; fi
}

# ---------- embedded app (a tar.gz appended to the end of this file) ----------
extract_payload() {  # extract_payload DIR
  local dir="$1" tmp; tmp="$(mktemp)"
  sed -n '/^__GRANTH_PAYLOAD__$/,$p' "$SELF" | tail -n +2 > "$tmp"
  mkdir -p "$dir"
  if base64 -D < "$tmp" 2>/dev/null | tar -xz -C "$dir" 2>/dev/null; then :
  elif base64 -d < "$tmp" 2>/dev/null | tar -xz -C "$dir" 2>/dev/null; then :
  elif python3 -c 'import base64,sys;sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' < "$tmp" | tar -xz -C "$dir"; then :
  else rm -f "$tmp"; die "could not unpack the app inside this file (was it edited or truncated? download it again)"; fi
  rm -f "$tmp"
}

# ---------- versions, backups ----------
app_version() { [ -f "$1/granth/config.py" ] && awk -F'"' '/^VERSION *=/{print $2; exit}' "$1/granth/config.py" || true; }
has_ai() {      # true when a key, Ollama model or custom server is already configured
  [ -f "$APP/.env" ] && grep -Eq '^([A-Z]+_API_KEY|OLLAMA_MODEL|CUSTOM_BASE_URL)=[^[:space:]]+' "$APP/.env"
}
backup_db() {   # copy the library database (service is stopped) and keep the 2 newest copies
  [ "${SKIP_BACKUP:-0}" = 1 ] && { say "      database backup skipped (SKIP_BACKUP=1)"; return 0; }
  [ -f "$DATA/library.db" ] || return 0
  local dir="$DATA/backups" ts f; ts="$(date +%Y%m%d-%H%M%S)"; mkdir -p "$dir"
  for f in library.db library.db-wal library.db-shm; do [ -f "$DATA/$f" ] && cp "$DATA/$f" "$dir/${f/library/library-$ts}"; done
  say "      database backed up to $dir/library-$ts.db ($(du -h "$DATA/library.db" | awk '{print $1}'))"
  ls -1t "$dir"/library-*.db 2>/dev/null | tail -n +3 | while read -r old; do rm -f "$old" "$old-wal" "$old-shm"; done
}

# ---------- service control ----------
svc_stop() {
  case "$(svc_mode)" in
    launchd) launchctl bootout "gui/$UIDN/$LABEL" >/dev/null 2>&1 || launchctl unload "$PLIST" >/dev/null 2>&1 || true ;;
    systemd) systemctl --user stop granth.service >/dev/null 2>&1 || true ;;
    plain)   [ -f "$DATA/granth.pid" ] && kill "$(cat "$DATA/granth.pid")" >/dev/null 2>&1; rm -f "$DATA/granth.pid" ;;
  esac
  pkill -f "[g]ranth serve" >/dev/null 2>&1 || true      # [g] trick: never matches this script itself
}
svc_start() {
  case "$(svc_mode)" in
    systemd) [ -f "$UNIT" ] || die "not installed yet. Run: $SELF"
             systemctl --user daemon-reload; systemctl --user enable --now granth.service >/dev/null 2>&1 \
               || die "systemd could not start the service. See: systemctl --user status granth"
             return ;;
    plain)   [ -x "$VENV/bin/python" ] || die "not installed yet. Run: $SELF"
             mkdir -p "$DATA/logs"
             # exec: the background process holds no handle on this terminal or on a pipe reading this script's output
             ( cd "$APP" && exec env GRANTH_DATA="$DATA" PYTHONUNBUFFERED=1 nohup "$VENV/bin/python" -m granth serve \
                 </dev/null >>"$DATA/logs/service.out.log" 2>>"$DATA/logs/service.err.log" ) &
             echo $! > "$DATA/granth.pid"
             return ;;
  esac
  [ -f "$PLIST" ] || die "not installed yet. Run: $SELF"
  launchctl enable "gui/$UIDN/$LABEL" >/dev/null 2>&1 || true
  local i
  for i in 1 2 3 4 5; do
    launchctl bootstrap "gui/$UIDN" "$PLIST" >/dev/null 2>&1 && break
    launchctl bootout "gui/$UIDN/$LABEL" >/dev/null 2>&1 || true; sleep 1
    if [ "$i" = 5 ]; then launchctl load -w "$PLIST" >/dev/null 2>&1 || die "launchd refused to start the service. Try: launchctl bootout gui/$UIDN/$LABEL ; then $SELF start"; fi
  done
  launchctl kickstart -k "gui/$UIDN/$LABEL" >/dev/null 2>&1 || true
}
wait_up() { local i; for i in $(seq 1 90); do curl -fsS "http://127.0.0.1:$PORT/healthz" >/dev/null 2>&1 && return 0; sleep 1; done; return 1; }
port_from_env() {
  [ -f "$APP/.env" ] && PORT="$(awk -F= '$1=="PORT"{print $2}' "$APP/.env" | tail -1)"; PORT="${PORT:-8000}"
  [ -f "$APP/.env" ] && ADMIN_PORT="$(awk -F= '$1=="ADMIN_PORT"{print $2}' "$APP/.env" | tail -1)"; ADMIN_PORT="${ADMIN_PORT:-8001}"
}

# ---------- AI choice ----------
ai_ollama() {
  say "Setting up Ollama (free AI that runs on this computer, no account or key)"
  export OLLAMA_HOST=127.0.0.1:11434     # pinned to this computer (its default is loopback; never trust a stray value)
  if [ "$OSK" = mac ]; then
    command -v brew >/dev/null 2>&1 || die "Homebrew is required for Ollama (https://brew.sh)"
    command -v ollama >/dev/null 2>&1 || brew install ollama || die "could not install Ollama"
    brew services start ollama >/dev/null 2>&1 || (OLLAMA_HOST=127.0.0.1:11434 nohup ollama serve >/dev/null 2>&1 &)
  else
    if ! command -v ollama >/dev/null 2>&1; then
      say "      installing Ollama with its official installer (asks for your password)"
      curl -fsSL https://ollama.com/install.sh | sh || die "could not install Ollama (see https://ollama.com/download/linux)"
    fi
    as_root systemctl enable --now ollama >/dev/null 2>&1 || (nohup ollama serve >/dev/null 2>&1 &)
  fi
  local i; for i in $(seq 1 30); do curl -fsS http://127.0.0.1:11434 >/dev/null 2>&1 && break; sleep 1; done
  curl -fsS http://127.0.0.1:11434 >/dev/null 2>&1 || die "Ollama did not start. Open the Ollama app once, then run: $SELF ai"
  local mem_gb model="$OLLAMA_MODEL"
  mem_gb="$(mem_gb)"
  if [ -z "$model" ]; then
    if   [ "$mem_gb" -ge 24 ]; then model="qwen2.5:14b"
    elif [ "$mem_gb" -ge 8  ]; then model="qwen2.5:7b"
    else model="qwen2.5:3b"; warn "only ${mem_gb} GB RAM: using a small model; Indian-language answers will be weaker"; fi
  fi
  say "Downloading model $model (several GB, one time)…"
  ollama pull "$model" || die "model download failed (check your internet and disk space)"
  setkv OLLAMA_MODEL "$model"
  say "Ollama ready with $model"
}
ai_key() {
  echo "  Free AI keys (no card needed):"
  echo "    1) Groq        https://console.groq.com"
  echo "    2) Gemini      https://aistudio.google.com"
  echo "    3) NVIDIA      https://build.nvidia.com"
  echo "    4) Cerebras    https://cloud.cerebras.ai"
  echo "    5) OpenRouter  https://openrouter.ai"
  echo "    6) Mistral     https://console.mistral.ai"
  local c name var key
  c="$(ask '  Which one did you sign up for [1-6]? ' 1)"
  case "$c" in 1) var=GROQ_API_KEY;; 2) var=GEMINI_API_KEY;; 3) var=NVIDIA_API_KEY;; 4) var=CEREBRAS_API_KEY;; 5) var=OPENROUTER_API_KEY;; 6) var=MISTRAL_API_KEY;; *) warn "skipped"; return;; esac
  printf '  Paste the key (hidden): '; read -r -s key </dev/tty 2>/dev/null || key=""; echo
  [ -n "$key" ] || { warn "no key entered"; return; }
  setkv "$var" "$key"; say "saved $var"
}
ai_menu() {
  local choice="${AI:-}"
  if [ -z "$choice" ] && ! has_tty; then
    choice=skip; warn "no terminal to ask which AI to use; skipping (run: $SELF ai  later, or set AI=ollama|key)"
  fi
  if [ -z "$choice" ]; then
    echo; echo "  Granth needs an AI writer to compose answers from your books."
    echo "    1) Ollama   - runs on this Mac, no key, works offline (needs ~8 GB RAM, ~5 GB download)"
    echo "    2) Free online key (Groq / Gemini / …) - fast, needs a free sign-up"
    echo "    3) Skip for now (you will see matching passages with page numbers only)"
    case "$(ask '  Choose [1-3]: ' 1)" in 1) choice=ollama;; 2) choice=key;; *) choice=skip;; esac
  fi
  case "$choice" in ollama) ai_ollama;; key) ai_key;; *) say "AI setup skipped (run: $SELF ai  to add it later)";; esac
}

# ---------- commands ----------
do_install() {
  local PY=""
  if [ "$OSK" = mac ]; then
    say "[1/7] Checking Homebrew and tools"
    command -v brew >/dev/null 2>&1 || die "Homebrew is required. Install it from https://brew.sh , then run this file again."
    local need=""
    if [ -z "${PYTHON_BIN:-}" ]; then brew list python@3.12 >/dev/null 2>&1 || need="$need python@3.12"; fi
    command -v tesseract >/dev/null 2>&1 || need="$need tesseract"
    brew list tesseract-lang >/dev/null 2>&1 || need="$need tesseract-lang"
    command -v pdftoppm >/dev/null 2>&1 || need="$need poppler"
    if [ -n "$need" ]; then say "      installing:$need"; brew install $need || warn "brew could not install everything; OCR of scanned books may be unavailable"; fi
    PY="${PYTHON_BIN:-$(brew --prefix python@3.12 2>/dev/null)/bin/python3.12}"
    [ -x "$PY" ] || PY="$(command -v python3.12 || true)"
    [ -x "$PY" ] || die "Python 3.12 not found. Run: brew install python@3.12"
  elif [ "$OSK" = linux ]; then
    say "[1/7] Checking Python and tools (Ubuntu/Debian)"
    command -v apt-get >/dev/null 2>&1 || warn "apt-get not found: install Python 3.10+, python3-venv, tesseract-ocr and poppler-utils yourself"
    local pkgs="python3 python3-venv python3-pip curl poppler-utils tesseract-ocr tesseract-ocr-eng tesseract-ocr-guj tesseract-ocr-hin tesseract-ocr-mar tesseract-ocr-san tesseract-ocr-tam tesseract-ocr-tel tesseract-ocr-kan tesseract-ocr-mal tesseract-ocr-ben tesseract-ocr-pan tesseract-ocr-urd tesseract-ocr-ori" missing="" p
    if command -v dpkg-query >/dev/null 2>&1; then
      for p in $pkgs; do dpkg-query -W -f='${Status}' "$p" 2>/dev/null | grep -q "install ok installed" || missing="$missing $p"; done
    fi
    if [ -n "$missing" ] && command -v apt-get >/dev/null 2>&1; then
      say "      installing:$missing  (asks for your password)"
      { as_root apt-get update -qq && as_root env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq $missing; } \
        || warn "could not install everything; scanned books may not be readable (OCR). Text books still work."
    fi
    PY="${PYTHON_BIN:-$(command -v python3.12 || command -v python3.13 || command -v python3.11 || command -v python3 || true)}"
    [ -x "$PY" ] || die "Python 3 not found. Run: sudo apt install python3 python3-venv"
    "$PY" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' || die "Python 3.10 or newer is needed (found $("$PY" -V 2>&1))"
    "$PY" -c 'import venv, ensurepip' 2>/dev/null || die "Python's venv module is missing. Run: sudo apt install python3-venv"
  else
    die "this file installs on macOS and Ubuntu/Debian Linux. For Windows use granth_setup.cmd from the Windows package."
  fi

  say "[2/7] Stopping any running copy"
  svc_stop
  mkdir -p "$APP" "$DATA/logs" "$BOOKS_DIR"

  local stage updating=0 restored=0 old_ver new_ver; stage="$(mktemp -d)"
  extract_payload "$stage"
  new_ver="$(app_version "$stage")"; old_ver="$(app_version "$APP")"
  if [ -d "$APP/granth" ]; then
    updating=1
    say "[3/7] Updating Granth ${old_ver:-?} -> ${new_ver:-?}  (settings, keys, chats and index are kept)"
    rm -rf "$PREV"; mkdir -p "$PREV"
    cp -R "$APP/granth" "$PREV/granth"; cp "$APP"/requirements*.txt "$PREV/" 2>/dev/null || true
    say "      previous version saved for: $SELF rollback"
    backup_db
  else
    say "[3/7] Installing Granth ${new_ver:-} to $APP"
  fi
  rm -rf "$APP/granth"; cp -R "$stage/granth" "$APP/granth"
  cp "$stage"/requirements*.txt "$APP/"
  if [ ! -f "$APP/.env" ] && [ -f "$DATA/settings.env" ]; then
    cp "$DATA/settings.env" "$APP/.env"; chmod 600 "$APP/.env"; say "      restored your settings and keys from the last install"
    restored=1
  fi
  [ -f "$APP/.env" ] || cp "$stage/.env.example" "$APP/.env"
  rm -rf "$stage"
  cp "$SELF" "$HOME_DIR/granth_setup.sh" 2>/dev/null && chmod +x "$HOME_DIR/granth_setup.sh"

  say "[4/7] Python environment"
  local want have
  want="$("$PY" -c 'import sys;print("%d.%d"%sys.version_info[:2])')"
  have="$("$VENV/bin/python" -c 'import sys;print("%d.%d"%sys.version_info[:2])' 2>/dev/null || echo none)"
  if [ "$have" != "$want" ]; then rm -rf "$VENV"; "$PY" -m venv "$VENV" || die "could not create the Python environment"; fi
  "$VENV/bin/pip" install --quiet --upgrade pip
  "$VENV/bin/pip" install --quiet -r "$APP/requirements.txt" || die "pip install failed (see messages above)"
  if [ "$WITH_SEMANTIC" = "1" ]; then
    say "      installing meaning-based search (large download; skip with WITH_SEMANTIC=0)"
    "$VENV/bin/pip" install --quiet -r "$APP/requirements-semantic.txt" || warn "semantic search not installed; keyword search still works"
  fi
  repair_main_venv
  if [ "$WITH_INDIC" = "1" ] || [ -d "$VENV_INDIC" ]; then
    install_indic_env; [ "$?" = 1 ] && warn "IndicTrans2 not installed; translation uses the AI"
  fi
  "$VENV/bin/python" -c "import sys; sys.path.insert(0,'$APP'); import granth.app, granth.textnorm" || die "self-check failed: the app cannot start (see error above)"

  say "[5/7] Settings"
  setkv IMPORT_DIR "$BOOKS_DIR"; setkv PORT "$PORT"; setkv SCAN_INTERVAL "30"
  setkv HOST "127.0.0.1"; setkv ALLOW_LAN "0"           # this computer only; never the network
  setkv ADMIN_PORT "$ADMIN_PORT"; setkv ADMIN_HOST "127.0.0.1"   # admin page: its own port, this computer only

  say "[6/7] AI writer"
  if { [ "$updating" = 1 ] || [ "$restored" = 1 ]; } && [ -z "${AI:-}" ] && has_ai; then
    say "      keeping your current AI settings (change them with: $SELF ai)"
  else
    ai_menu
  fi

  say "[7/7] Starting the background service"
  local mode; mode="$(svc_mode)"
  if [ "$mode" = launchd ]; then
    mkdir -p "$HOME/Library/LaunchAgents"
    [ -w "$HOME/Library/LaunchAgents" ] || die "cannot write to ~/Library/LaunchAgents. Fix with: sudo chown -R $USER ~/Library/LaunchAgents"
    cat > "$PLIST" <<PEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$LABEL</string>
  <key>ProgramArguments</key><array><string>$VENV/bin/python</string><string>-m</string><string>granth</string><string>serve</string></array>
  <key>WorkingDirectory</key><string>$APP</string>
  <key>EnvironmentVariables</key><dict>
    <key>GRANTH_DATA</key><string>$DATA</string>
    <key>PATH</key><string>/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin</string>
    <key>PYTHONUNBUFFERED</key><string>1</string>
  </dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>10</integer>
  <key>StandardOutPath</key><string>$DATA/logs/service.out.log</string>
  <key>StandardErrorPath</key><string>$DATA/logs/service.err.log</string>
</dict></plist>
PEOF
  elif [ "$mode" = systemd ]; then
    mkdir -p "$UNIT_DIR"
    cat > "$UNIT" <<UEOF
[Unit]
Description=Swaminarayan Sampradaya library chat (Granth)
After=network-online.target

[Service]
WorkingDirectory=$APP
Environment=GRANTH_DATA=$DATA
Environment=PYTHONUNBUFFERED=1
ExecStart=$VENV/bin/python -m granth serve
Restart=always
RestartSec=5
StandardOutput=append:$DATA/logs/service.out.log
StandardError=append:$DATA/logs/service.err.log

[Install]
WantedBy=default.target
UEOF
    echo systemd > "$HOME_DIR/.service-mode"
    # start at boot even before anyone logs in (needs root once; skipped quietly if not allowed)
    loginctl show-user "$USER" 2>/dev/null | grep -q '^Linger=yes' || as_root loginctl enable-linger "$USER" >/dev/null 2>&1 \
      || warn "the library starts when you log in (to start at boot: sudo loginctl enable-linger $USER)"
  else
    echo plain > "$HOME_DIR/.service-mode"
    warn "no systemd user session here: the library runs as a background process"
    if command -v crontab >/dev/null 2>&1; then          # and starts again after a reboot
      ( crontab -l 2>/dev/null | grep -v 'granth_setup.sh start'; echo "@reboot $HOME_DIR/granth_setup.sh start >/dev/null 2>&1" ) | crontab - 2>/dev/null \
        || warn "could not add the start-at-boot entry; after a reboot run: $HOME_DIR/granth_setup.sh start"
    fi
  fi
  svc_start
  if wait_up; then
    local token; token="$(cat "$DATA/admin_token" 2>/dev/null || echo '(created on first start)')"
    cat <<DONE

  ✅ Granth is running:  http://localhost:$PORT
  🛡  Admin page:          http://localhost:$ADMIN_PORT   (this computer only)
  📚 Put your books in:  $BOOKS_DIR     (PDF, scans/photos, EPUB, DOCX, TXT, HTML …) — indexed automatically
  🔑 Admin token:        $token
  Commands:   ~/granth/granth_setup.sh  status | logs | open | admin | restart | stop | ai | update | rollback | version | uninstall
  Questions it could not answer are listed in the Admin panel and in $DATA/logs/unanswered.jsonl
  Tip: keep books OUTSIDE Documents/Desktop/Downloads (macOS blocks background apps there).
DONE
    [ "$updating" = 1 ] && echo "  Updated ${old_ver:-?} -> ${new_ver:-?}. If anything is wrong, go back with:  $SELF rollback"
    open_url "http://localhost:$PORT"
  else
    warn "the service did not answer within 90 s. Last log lines:"; tail -n 25 "$DATA/logs/service.err.log" 2>/dev/null
    die "see the log above, or run: $SELF logs"
  fi
}

do_ai() {
  [ -f "$APP/.env" ] || die "not installed yet. Run: $SELF"
  AI="" ai_menu
  svc_stop; sleep 1; svc_start
  wait_up && say "restarted. Test: cd $APP && ../venv/bin/python -m granth check-providers" || warn "restart is taking long; see: $SELF logs"
}

do_rollback() {
  [ -d "$PREV/granth" ] || die "no previous version is saved (one is kept automatically when you update)"
  local cur prev; cur="$(app_version "$APP")"; prev="$(app_version "$PREV")"
  say "Rolling back ${cur:-?} -> ${prev:-?}"
  svc_stop
  rm -rf "$APP/granth"; cp -R "$PREV/granth" "$APP/granth"
  cp "$PREV"/requirements*.txt "$APP/" 2>/dev/null || true
  "$VENV/bin/pip" install --quiet -r "$APP/requirements.txt" || warn "pip could not install everything for the older version"
  rm -rf "$PREV"
  svc_start
  if wait_up; then say "running ${prev:-the previous version} again: http://localhost:$PORT"; else warn "not up yet; see: $SELF logs"; fi
  echo "  Your settings, chats and index were kept. Database copies from before the update are in $DATA/backups."
  echo "  To update again later, run the newer setup file."
}

INDIC_PACKAGES="torch>=2.2 transformers>=4.40,<4.47 sentencepiece>=0.2 IndicTransToolkit>=1.0"

repair_main_venv() {   # 2.9.0/2.9.1 put IndicTrans2 into the app's environment, which broke meaning-based search
  [ -x "$VENV/bin/python" ] || return 0
  if "$VENV/bin/python" -c "import IndicTransToolkit" >/dev/null 2>&1; then
    say "      moving IndicTrans2 out of the app's environment (it now has its own; this fixes the package conflict)"
    "$VENV/bin/pip" uninstall -y -q IndicTransToolkit >/dev/null 2>&1 || true
  fi
  if [ "$WITH_SEMANTIC" = "1" ] || "$VENV/bin/python" -c "import sentence_transformers" >/dev/null 2>&1; then
    if [ "${FORCE_REPAIR:-0}" = 1 ] || ! "$VENV/bin/pip" check >/dev/null 2>&1; then
      say "      repairing meaning-based search packages"
      local extra=""
      "$VENV/bin/python" -c "import fastembed" >/dev/null 2>&1 && extra="fastembed>=0.3"
      # shellcheck disable=SC2086
      "$VENV/bin/pip" install --quiet --upgrade -r "$APP/requirements-semantic.txt" $extra \
        || warn "could not repair meaning-based search; keyword search still works"
    fi
  fi
  "$VENV/bin/pip" check >/dev/null 2>&1 || warn "some packages still conflict: $("$VENV/bin/pip" check 2>&1 | head -3 | tr '\n' ' ')"
}

indic_check() {   # indic_check TOKEN -> prints one line per model; exit 0 when all three can be downloaded
  PYTHONPATH="$APP" HF_TOKEN="$1" HF_HUB_DISABLE_TELEMETRY=1 "$VENV_INDIC/bin/python" - <<'PYEOF3'
import os, sys
from granth.indictrans import check_access
res = check_access(os.environ.get("HF_TOKEN") or None)
for repo, ok, msg in res:
    print(("   ok       " if ok else "   missing  ") + repo + ("" if ok else "  -> " + msg))
sys.exit(0 if all(ok for _, ok, _ in res) else 1)
PYEOF3
}

indic_access() {  # make sure the gated models can be downloaded; asks for a Hugging Face token when needed
  local tok try=0
  tok="${HF_TOKEN:-$(awk -F= '$1=="HF_TOKEN"{sub(/^HF_TOKEN=/,""); print}' "$APP/.env" 2>/dev/null | tail -1)}"
  say "      checking access to the IndicTrans2 models on Hugging Face"
  while :; do
    if indic_check "$tok"; then
      [ -n "$tok" ] && setkv HF_TOKEN "$tok"
      return 0
    fi
    try=$((try + 1))
    if [ "$try" -gt 3 ] || ! has_tty; then return 1; fi
    cat <<'HELP'

  AI4Bharat shares these models only with signed-in users who accept their conditions (free):
    1. Create a free account (or sign in):  https://huggingface.co/join
    2. Open each page below, sign in, and click "Agree and access repository" (fill in the short form):
         https://huggingface.co/ai4bharat/indictrans2-en-indic-dist-200M
         https://huggingface.co/ai4bharat/indictrans2-indic-en-dist-200M
         https://huggingface.co/ai4bharat/indictrans2-indic-indic-dist-320M
    3. Create a token with "Read" access:  https://huggingface.co/settings/tokens
  Then paste the token here (it starts with hf_; it is saved only in your settings file on this Mac).
  Press Enter without a token to stop for now; translation keeps using the AI.

HELP
    local t=""
    { read -r -s -p "  Hugging Face token: " t </dev/tty; echo; } 2>/dev/null || t=""
    t="$(printf '%s' "$t" | tr -d '[:space:]')"
    [ -z "$t" ] && return 1
    case "$t" in hf_*) ;; *) warn "that does not look like a Hugging Face token (they start with hf_)";; esac
    tok="$t"
    setkv HF_TOKEN "$tok"            # kept for next time, e.g. while AI4Bharat reviews an access request
  done
}

install_indic_env() {  # IndicTrans2 in ~/granth/venv-indic. Returns 1: packages failed; 2: no access to the models
  local base req=""
  base="$("$VENV/bin/python" -c 'import sys;print(sys._base_executable)' 2>/dev/null)"
  [ -x "$base" ] || base="$VENV/bin/python"
  for f in "$APP/requirements-indic.txt" "$(dirname "$SELF")/requirements-indic.txt"; do [ -f "$f" ] && { req="$f"; break; }; done
  say "      offline Indian-language translation (IndicTrans2) in its own environment: $VENV_INDIC"
  [ -x "$VENV_INDIC/bin/python" ] || "$base" -m venv "$VENV_INDIC" || return 1
  "$VENV_INDIC/bin/pip" install --quiet --upgrade pip
  if [ -n "$req" ]; then "$VENV_INDIC/bin/pip" install -r "$req" || return 1
  else
    # shellcheck disable=SC2086
    "$VENV_INDIC/bin/pip" install $INDIC_PACKAGES || return 1
  fi
  PYTHONPATH="$APP" "$VENV_INDIC/bin/python" -c "from granth import indictrans; import sys; sys.exit(0 if indictrans.available() else 1)" \
    || { warn "IndicTrans2 installed but cannot be loaded"; return 1; }
  setkv TRANSLATE_ENGINE "auto"
  if ! indic_access; then
    delkv INDIC_PYTHON                     # not used until the models can be downloaded
    warn "no access to the IndicTrans2 models yet, so translation keeps using the AI."
    warn "When access is granted on Hugging Face, run: $SELF indic"
    return 2
  fi
  # download the models now (about 3 GB), so no reader waits for a download later
  say "      downloading the IndicTrans2 models (about 3 GB, once) and checking which processor is fastest"
  mkdir -p "$DATA/models/indictrans2"
  local tok; tok="$(awk -F= '$1=="HF_TOKEN"{sub(/^HF_TOKEN=/,""); print}' "$APP/.env" 2>/dev/null | tail -1)"
  if PYTHONPATH="$APP" HF_TOKEN="$tok" HF_HUB_DISABLE_TELEMETRY=1 "$VENV_INDIC/bin/python" - "$DATA/models/indictrans2" <<'PYEOF2'
import sys, time
from granth.indictrans import IndicTrans2, ModelAccessError
e = IndicTrans2(sys.argv[1])
try:
    for src, tgt, label in (("en", "gu", "English -> Indian languages"), ("gu", "en", "Indian languages -> English"),
                            ("gu", "hi", "between Indian languages")):
        t0 = time.time()
        e._get(src, tgt)
        out = e.translate("The devotee asked a question." if src == "en" else "ભક્તે પ્રશ્ન પૂછ્યો.", tgt, beams=1)
        print(f"   ready: {label} ({time.time() - t0:.0f}s)  sample: {out}")
except ModelAccessError as err:
    print("   " + str(err)); sys.exit(2)
PYEOF2
  then
    setkv INDIC_PYTHON "$VENV_INDIC/bin/python"
  else
    delkv INDIC_PYTHON
    warn "the models could not be downloaded (see above); translation keeps using the AI. Try again: $SELF indic"
    return 2
  fi
}

do_indic() {    # ./granth_setup.sh indic [remove]
  [ -x "$VENV/bin/pip" ] || die "install the app first: $SELF"
  if [ "${1:-}" = "remove" ] || [ "${1:-}" = "uninstall" ]; then do_indic_remove; return; fi
  local here stage; stage="$(mktemp -d)"; extract_payload "$stage"; here="$(app_version "$stage")"; rm -rf "$stage"
  if [ "$(app_version "$APP")" != "$here" ] || [ ! -f "$APP/granth/indic_worker.py" ]; then
    say "The installed app is $(app_version "$APP" || echo old); this file has $here. Updating it first, with IndicTrans2."
    WITH_INDIC=1 do_install
    return
  fi
  say "Installing IndicTrans2 (AI4Bharat, MIT licence): about 1 GB of packages and 3 GB of models. This takes a while once."
  repair_main_venv
  install_indic_env; local rc=$?
  [ "$rc" = 1 ] && die "IndicTrans2 could not be installed (see messages above). The app still translates with the AI."
  svc_stop; sleep 1; svc_start
  [ "$rc" = 2 ] && return 0
  say "Done. Translation uses IndicTrans2 when no Gemini/OpenAI/Mistral/DeepSeek key is set."
  say "To always use it, set TRANSLATE_ENGINE=indictrans2 in $APP/.env, then: $SELF restart"
  say "To remove it later: $SELF indic remove"
}

do_indic_remove() {
  local freed=0 d
  say "Removing IndicTrans2"
  svc_stop
  for d in "$VENV_INDIC" "$DATA/models/indictrans2" "$DATA"/models/models--ai4bharat--indictrans2*; do
    [ -e "$d" ] || continue
    freed=$((freed + $(du -sk "$d" 2>/dev/null | awk '{print $1}')))
    rm -rf "$d"
  done
  if [ -x "$VENV/bin/python" ] && "$VENV/bin/python" -c "import IndicTransToolkit" >/dev/null 2>&1; then
    "$VENV/bin/pip" uninstall -y -q IndicTransToolkit >/dev/null 2>&1 || true      # left by 2.9.0/2.9.1
  fi
  repair_main_venv
  delkv INDIC_PYTHON
  delkv HF_TOKEN
  setkv TRANSLATE_ENGINE "llm"
  svc_start
  say "Removed (freed about $((freed / 1024)) MB). Translation uses the AI again. Add it back any time: $SELF indic"
}

do_version() {
  local here stage; stage="$(mktemp -d)"; extract_payload "$stage"; here="$(app_version "$stage")"; rm -rf "$stage"
  echo "installed:      $(app_version "$APP" || true)${APP:+  ($APP)}"
  echo "in this file:   ${here:-?}"
  [ -d "$PREV/granth" ] && echo "rollback to:    $(app_version "$PREV")"
  return 0
}

do_uninstall() {
  local yes=0 withollama=0 all=0 a
  for a in "$@"; do case "$a" in -y|--yes) yes=1;; --with-ollama) withollama=1;; --all) all=1; withollama=1;; esac; done
  say "Removing the Granth service"
  svc_stop
  launchctl disable "gui/$UIDN/$LABEL" >/dev/null 2>&1 || true
  rm -f "$PLIST"
  if [ -f "$UNIT" ]; then systemctl --user disable --now granth.service >/dev/null 2>&1 || true; rm -f "$UNIT"; systemctl --user daemon-reload >/dev/null 2>&1 || true; fi
  if command -v crontab >/dev/null 2>&1 && crontab -l 2>/dev/null | grep -q 'granth_setup.sh start'; then
    crontab -l 2>/dev/null | grep -v 'granth_setup.sh start' | crontab - 2>/dev/null || true
  fi
  if [ "$yes" = 1 ] || [ "$all" = 1 ]; then a=y; else a="$(ask 'Also delete the index, chat history, downloaded models and logs in ~/granth/data? [y/N] ' n)"; fi
  rm -rf "$VENV_INDIC"
  case "$a" in y|Y) rm -rf "$HOME_DIR"; say "removed ~/granth";; *) [ -f "$APP/.env" ] && { cp "$APP/.env" "$DATA/settings.env"; chmod 600 "$DATA/settings.env"; }
     rm -rf "$APP" "$VENV" "$PREV"; say "kept ~/granth/data, including your settings and keys (delete the folder ~/granth later if you want)";; esac
  if [ "$withollama" = 0 ] && [ "$yes" = 0 ] && command -v ollama >/dev/null 2>&1; then
    [ "$(ask 'Also remove Ollama and its downloaded models? [y/N] ' n)" = y ] && withollama=1
  fi
  if [ "$withollama" = 1 ]; then
    if [ "$OSK" = mac ]; then
      brew services stop ollama >/dev/null 2>&1 || true; brew uninstall ollama >/dev/null 2>&1 || true
    else
      as_root systemctl disable --now ollama >/dev/null 2>&1 || true
      as_root rm -f /usr/local/bin/ollama /usr/bin/ollama /etc/systemd/system/ollama.service >/dev/null 2>&1 || true
      as_root rm -rf /usr/share/ollama >/dev/null 2>&1 || true
    fi
    rm -rf "$HOME/.ollama"; say "removed Ollama"
  fi
  if [ "$all" = 0 ] && [ "$yes" = 0 ] && command -v brew >/dev/null 2>&1; then
    [ "$(ask 'Also remove the Homebrew tools setup installed for reading scans (tesseract, tesseract-lang, poppler)? [y/N] ' n)" = y ] && all=2
  fi
  if [ "$OSK" = linux ] && [ "$all" = 0 ] && [ "$yes" = 0 ] && command -v apt-get >/dev/null 2>&1; then
    [ "$(ask 'Also remove the OCR tools setup installed (tesseract-ocr and its languages, poppler-utils)? [y/N] ' n)" = y ] && all=2
  fi
  if [ "$all" -ge 1 ] && command -v brew >/dev/null 2>&1; then
    for a in tesseract-lang tesseract poppler; do brew uninstall --ignore-dependencies "$a" >/dev/null 2>&1 && say "removed $a"; done
  fi
  if [ "$all" -ge 1 ] && [ "$OSK" = linux ] && command -v apt-get >/dev/null 2>&1; then
    as_root env DEBIAN_FRONTEND=noninteractive apt-get remove -y -qq 'tesseract-ocr*' poppler-utils >/dev/null 2>&1 && say "removed tesseract-ocr and poppler-utils"
  fi
  rm -f "$HOME_DIR/.service-mode"
  if [ "$all" = 1 ] || { [ "$yes" = 0 ] && [ "$(ask "Also clear pip's download cache (frees the PyTorch downloads)? [y/N] " n)" = y ]; }; then
    rm -rf "$HOME/Library/Caches/pip" "$HOME/.cache/pip"; say "cleared pip's download cache"
  fi
  [ "$all" = 1 ] && rm -rf "$HOME_DIR"
  echo "Done. Your books folder ($BOOKS_DIR) was NOT touched. Python itself was kept (other apps may use it)."
}

do_status() {    # everything an operator checks first
  local mode h a; mode="$(svc_mode)"
  echo "Granth $(app_version "$APP" || echo '?')   app: $APP   data: $DATA   service: $mode"
  case "$mode" in
    launchd) launchctl print "gui/$UIDN/$LABEL" 2>/dev/null | awk '/state =|pid =|last exit code/{gsub(/^[ \t]+/,"");print "  "$0}' || echo "  service: not loaded" ;;
    systemd) systemctl --user --no-pager status granth.service 2>/dev/null | sed -n '1,4p' | sed 's/^/  /' || echo "  service: not installed" ;;
    plain)   if [ -f "$DATA/granth.pid" ] && kill -0 "$(cat "$DATA/granth.pid")" 2>/dev/null; then echo "  running, pid $(cat "$DATA/granth.pid")"; else echo "  not running"; fi ;;
  esac
  h="$(curl -fsS -m 5 "http://127.0.0.1:$PORT/healthz" 2>/dev/null)"; echo "  library chat (port $PORT): ${h:-NOT ANSWERING}"
  a="$(curl -fsS -m 5 "http://127.0.0.1:$ADMIN_PORT/healthz" 2>/dev/null)"; echo "  admin page   (port $ADMIN_PORT): ${a:-NOT ANSWERING}"
  if curl -fsS -m 3 http://127.0.0.1:11434 >/dev/null 2>&1; then echo "  Ollama: running"; fi
  echo "  disk: data $(du -sh "$DATA" 2>/dev/null | awk '{print $1}'), free $(df -h "$HOME" | awk 'NR==2{print $4}')"
  if [ -f "$DATA/logs/granth.log" ]; then
    local n; n="$(grep -c ' ERROR \| CRITICAL ' "$DATA/logs/granth.log" 2>/dev/null || true)"
    echo "  errors in the current log: ${n:-0}   (details: $SELF logs, or the admin page > Log files)"
  fi
}
do_health() {    # for monitors and scripts: prints OK/FAIL and exits 0/1
  if curl -fsS -m 5 "http://127.0.0.1:$PORT/healthz" >/dev/null 2>&1 && curl -fsS -m 5 "http://127.0.0.1:$ADMIN_PORT/healthz" >/dev/null 2>&1; then
    echo "OK granth $(app_version "$APP") on ports $PORT/$ADMIN_PORT"; exit 0
  fi
  echo "FAIL granth is not answering on port $PORT or $ADMIN_PORT (try: $SELF restart; details: $SELF logs)"; exit 1
}

port_from_env
case "${1:-install}" in
  install|update) do_install ;;
  rollback)  do_rollback ;;
  version)   do_version ;;
  ai)        do_ai ;;
  indic)     shift; do_indic "$@" ;;
  repair)    [ -x "$VENV/bin/pip" ] || die "install the app first: $SELF"
             say "Checking the app's Python packages"
             svc_stop; FORCE_REPAIR=1 repair_main_venv
             "$VENV/bin/pip" check && say "No conflicts."
             svc_start ;;
  status)    do_status ;;
  health)    do_health ;;
  ports)     # shows what is listening and warns if anything is reachable from other computers
    port_from_env
    echo "Library chat ($PORT), admin page ($ADMIN_PORT) and Ollama (11434) listeners:"
    listeners() {
      if command -v lsof >/dev/null 2>&1; then lsof -nP -iTCP:"$PORT" -iTCP:"$ADMIN_PORT" -iTCP:11434 -sTCP:LISTEN 2>/dev/null | awk 'NR>1{print $9}'
      else ss -ltnH 2>/dev/null | awk -v a=":$PORT" -v b=":$ADMIN_PORT" '$4 ~ a"$" || $4 ~ b"$" || $4 ~ /:11434$/ {print $4}'; fi; }
    listeners | sed 's/^/  /'; [ -n "$(listeners)" ] || echo "  (none listening)"
    if listeners | grep -vq '127.0.0.1:\|\[::1\]:'; then
      warn "something is reachable from other computers. Run: $SELF stop, then check HOST/OLLAMA_HOST in $APP/.env"
    else
      say "OK: only this computer can reach Granth and Ollama. Keep the firewall on (macOS: System Settings > Network > Firewall; Ubuntu: sudo ufw enable)."
    fi ;;
  logs)      exec tail -n 80 -f "$DATA/logs/granth.log" "$DATA/logs/service.err.log" ;;
  open)      open_url "http://localhost:$PORT" ;;
  admin)     open_url "http://localhost:$ADMIN_PORT" ;;
  start)     svc_start; wait_up && echo "running: http://localhost:$PORT" || echo "not up yet; see: $SELF logs" ;;
  stop)      svc_stop; echo stopped ;;
  restart)   svc_stop; sleep 1; svc_start; wait_up && echo "running: http://localhost:$PORT" || echo "not up yet; see: $SELF logs" ;;
  uninstall) shift; do_uninstall "$@" ;;
  extract)   extract_payload "${2:?usage: extract DIR}"; echo "unpacked to $2" ;;
  help|-h|--help) awk 'NR>1 && /^# =====/{c++; if(c==2) exit} NR>1{print}' "$SELF" ;;
  *) die "unknown command: $1  (try: help)" ;;
esac
exit 0
